/** How often a recurring rule files an issue. */
export type RecurrenceCadence = "daily" | "weekly";

/**
 * A rule that files an ordinary issue on each occurrence. Dates are
 * `YYYY-MM-DD` calendar days in `timezone`; `weekday` is the ISO weekday
 * (1 = Monday … 7 = Sunday) and is only set for weekly rules.
 */
