/**
 * Recurring-issue rules. Reads are org-scoped except the job sweep, which is
 * cross-tenant on purpose: it is drained by a background worker, not a request.
 */
import { and, asc, count, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { RecurringIssue } from "@/types/recurring-issue";
import { orgPredicate } from "./base-repository";
import { toRecurringIssue } from "./_mappers";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";

export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(asc(recurringIssues.createdAt), asc(recurringIssues.id))
    .all()
    .map(toRecurringIssue);
}

export async function findRecurringIssueById(
  orgId: OrgId,
  recurringIssueId: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .get();
  return row ? toRecurringIssue(row) : null;
}

/** Every rule the quota counts, paused ones included. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

/** Cross-tenant on purpose: the job sweeps every organization's live rules. */
export async function listActiveRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(asc(recurringIssues.createdAt), asc(recurringIssues.id))
    .all()
    .map(toRecurringIssue);
}

export async function insertRecurringIssue(
  input: CreateRecurringIssueInput & {
    readonly orgId: OrgId;
    readonly assigneeId: UserId | null;
    readonly createdBy: UserId;
  },
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      title: input.title,
      priority: input.priority ?? "none",
      assigneeId: input.assigneeId,
      cadence: input.cadence,
      weekday: input.weekday ?? null,
      timezone: input.timezone,
      startsOn: input.startsOn,
      lastOccurrenceOn: null,
      paused: false,
      createdBy: input.createdBy,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toRecurringIssue(row);
}

export async function setRecurringIssuePaused(
  orgId: OrgId,
  recurringIssueId: string,
  paused: boolean,
  at: IsoTimestamp = toIsoTimestamp(new Date()),
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: at })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();
  return toRecurringIssue(row);
}

/** Records the occurrence day a rule last filed; never called on a failed run. */
export async function setLastOccurrenceOn(
  orgId: OrgId,
  recurringIssueId: string,
  occurrenceOn: string,
): Promise<void> {
  getDb()
    .update(recurringIssues)
    .set({
      lastOccurrenceOn: occurrenceOn,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .run();
}

