/**
 * Calendar arithmetic for recurring-issue rules.
 *
 * Occurrence days are `YYYY-MM-DD` strings with no time of day. Only the
 * instant → local-day step touches a time zone; everything after it is pure
 * date arithmetic on UTC midnights, so DST never shifts a day.
 */
import type { RecurrenceCadence } from "@/types/recurring-issue";

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;
const DAY_MS = 86_400_000;

/** True for a real `YYYY-MM-DD` calendar date (rejects e.g. `2026-02-30`). */
export function isCalendarDate(value: string): boolean {
  const match = CALENDAR_DATE.exec(value);
  if (match === null) return false;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const probe = new Date(Date.UTC(year, month - 1, day));

  return (
    probe.getUTCFullYear() === year &&
    probe.getUTCMonth() === month - 1 &&
    probe.getUTCDate() === day
  );
}

/** True when the runtime's ICU knows `timeZone` as an IANA zone. */
export function isValidTimeZone(timeZone: string): boolean {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone });
    return true;
  } catch {
    return false;
  }
}

/** The calendar day `instant` falls on in `timeZone`, as `YYYY-MM-DD`. */
export function localDateInZone(instant: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(instant);

  const pick = (type: Intl.DateTimeFormatPartTypes): string =>
    parts.find((part) => part.type === type)?.value ?? "";

  return `${pick("year")}-${pick("month")}-${pick("day")}`;
}

/** ISO weekday of a `YYYY-MM-DD` day: 1 = Monday … 7 = Sunday. */
export function isoWeekdayOf(day: string): number {
  const dayOfWeek = new Date(`${day}T00:00:00Z`).getUTCDay();
  return dayOfWeek === 0 ? 7 : dayOfWeek;
}

/** Adds a signed number of calendar days to a `YYYY-MM-DD` day. */
export function addDays(day: string, delta: number): string {
  const shifted = new Date(Date.parse(`${day}T00:00:00Z`) + delta * DAY_MS);
  return shifted.toISOString().slice(0, 10);
}

/**
 * The latest occurrence day on or before `today` (a `YYYY-MM-DD` day in the
 * rule's zone), or `null` when none has started yet. Occurrences before
 * `startsOn` do not exist.
 */
export function latestOccurrenceOnOrBefore(
  rule: {
    readonly cadence: RecurrenceCadence;
    readonly weekday: number | null;
    readonly startsOn: string;
  },
  today: string,
): string | null {
  if (today < rule.startsOn) return null;

  if (rule.cadence === "daily" || rule.weekday === null) {
    return today;
  }

  const back = (isoWeekdayOf(today) - rule.weekday + 7) % 7;
  const candidate = addDays(today, -back);
  return candidate < rule.startsOn ? null : candidate;
}

