/**
 * Recurring-issue rules: who may define one, how many a plan allows, and who may pause or read them. Filing the issues themselves is the job's concern.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, wouldExceedLimit, createRecurringIssueSchema
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import {
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { OrgId } from "@/types/common";
import type { RecurringIssue } from "@/types/recurring-issue";
import type { Actor } from "@/types/member";

/**
 * Defines a rule after the same gates an issue create passes: tenant scope,
 * a live project, the `issue:create` permission in that project, an active
 * assignee, and the plan's rule cap. Nothing is stored unless all of them hold.
 */
export async function createRecurringIssue(
  actor: Actor,
  input: CreateRecurringIssueInput,
): Promise<RecurringIssue> {
  const parsed = createRecurringIssueSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(parsed.orgId, parsed.projectId),
    "Project",
    parsed.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(parsed.orgId),
    "Organization",
    parsed.orgId,
  );

  if (parsed.assigneeId !== null) {
    const assignee = await memberRepo.findMember(parsed.orgId, parsed.assigneeId);
    if (assignee?.status !== "active") {
      throw new Error("The assignee must be an active member of this organization");
    }
  }

  // Paused rules count too: pausing frees nothing against the cap.
  const used = await recurringIssueRepo.countRecurringIssues(parsed.orgId);
  if (wouldExceedLimit(org.plan, "recurringIssues", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} recurring issues and no more`,
    );
  }

  return recurringIssueRepo.insertRecurringIssue({
    ...parsed,
    assigneeId: parsed.assigneeId,
    createdBy: actor.userId,
  });
}

/** Pausing is gated like creating an issue in the rule's project. */
export async function setRecurringIssuePaused(
  actor: Actor,
  input: { orgId: OrgId; recurringIssueId: string; paused: boolean },
): Promise<RecurringIssue> {
  assertOrgScope(actor, input.orgId);

  const rule = requireFound(
    await recurringIssueRepo.findRecurringIssueById(
      input.orgId,
      input.recurringIssueId,
    ),
    "RecurringIssue",
    input.recurringIssueId,
  );

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  return recurringIssueRepo.setRecurringIssuePaused(
    input.orgId,
    input.recurringIssueId,
    input.paused,
  );
}

/** Rules in creation order. Readable by anyone who may read issues. */
export async function listRecurringIssues(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "issue:read", orgResource(orgId));
  return recurringIssueRepo.listRecurringIssues(orgId);
}

