/**
 * Turns each live recurring-issue rule into at most one ordinary issue per run, for its latest started occurrence. Missed occurrences are never back-filled.
 *
 * Must call (do not reimplement): can, createIssue, localDateInZone, latestOccurrenceOnOrBefore, isArchived
 */
import { can } from "@/lib/permissions";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import {
  isoWeekdayOf,
  latestOccurrenceOnOrBefore,
  localDateInZone,
} from "@/lib/recurrence";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { projectResource, requireFound } from "@/server/services/_support";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { RecurringIssue } from "@/types/recurring-issue";
import type { Actor } from "@/types/member";

const logger = createLogger("recurring-issue-job");

/**
 * Files the due occurrence for every non-paused rule. A rule that fails is
 * counted and left exactly as it was, so a later run retries it; one rule's
 * failure never stops the rest.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        const filed = await fileDueOccurrence(rule, now);
        if (filed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/** Returns `true` when an issue was filed for this rule. */
async function fileDueOccurrence(
  rule: RecurringIssue,
  now: Date,
): Promise<boolean> {
  const today = localDateInZone(now, rule.timezone);
  const occurrence = latestOccurrenceOnOrBefore(rule, today);
  if (occurrence === null) return false;
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return false;
  }

  const project = requireFound(
    await projectRepo.findProjectById(rule.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  // An archived project is skipped, not paused: the next run after restore files the then-latest occurrence.
  if (isArchived(project)) return false;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const creatorActor: Actor | null =
    creator?.status === "active"
      ? { userId: creator.userId, orgId: rule.orgId, role: creator.role }
      : null;

  if (
    creatorActor === null ||
    !can(creatorActor, "issue:create", projectResource(project))
  ) {
    await recurringIssueRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    logger.warn("paused recurring issue whose creator may not file it", {
      recurringIssueId: rule.id,
    });
    return false;
  }

  const assignee =
    rule.assigneeId === null
      ? null
      : await memberRepo.findMember(rule.orgId, rule.assigneeId);

  await createIssue(creatorActor, {
    orgId: rule.orgId,
    projectId: rule.projectId,
    title: `${rule.title} (${occurrence})`,
    description: null,
    status: "backlog",
    priority: rule.priority,
    assigneeId: assignee?.status === "active" ? rule.assigneeId : null,
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  });

  await recurringIssueRepo.setLastOccurrenceOn(rule.orgId, rule.id, occurrence);
  return true;
}

